function R(seed){let x=(seed>>>0)||1;return{next(){x=(1664525*x+1013904223)>>>0;return x/4294967296},int(a,b){return Math.floor(this.next()*(b-a+1))+a},pick(a){return a[Math.floor(this.next()*a.length)]},shuffle(a){a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(this.next()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}}}
