const q=(question,options,answer,topic,explanation,difficulty,skill)=>({question,options:options.map(String),answer,topic,explanation,difficulty,skill,question_type:'multiple_choice'});
function uniqueOptions(correct,candidates,count,r){let a=[String(correct)];for(const v of r.shuffle(candidates.map(String))){if(!a.includes(v)&&a.length<count)a.push(v)}if(a.length<count){const n=Number(correct);if(Number.isFinite(n)){const deltas=[1,-1,2,-2,5,-5,10,-10,0.5,-0.5];for(const d of deltas){if(a.length>=count)break;const v=String(n+d);if(!a.includes(v))a.push(v)}}else{const fallbacks=['None of the other statements','The information is not stated','It cannot be determined from the information given'];for(const v of fallbacks){if(a.length>=count)break;if(!a.includes(v))a.push(v)}}}return r.shuffle(a)}
function mc(question,correct,candidates,meta,r){const options=uniqueOptions(correct,candidates,meta.options||5,r);return q(question,options,options.indexOf(String(correct)),meta.topic,meta.explanation,meta.difficulty,meta.skill)}
function difficulty(seed,i){const x=(seed*13+i*7)%100;return x<18?'Foundation':x<48?'Standard':x<73?'Selective':x<91?'Advanced':'Challenge'}

