function(r){const d=r.pick([4,5,6,8,10,12]),k=r.int(1,d-1),n=d*r.int(2,9),c=n*k/d;return mc(`A tank contains ${n} L. ${k}/${d} of the water is used. How many litres are used?`,c,[c+k,c-1,c+d,c*2,n-c],{topic:'Fractions',skill:'Apply a fraction to a quantity',explanation:'Multiply the whole amount by the fraction.',difficulty:''},r)},
function(r){const a=r.int(2,8),b=r.int(3,9),unit=r.int(3,12),c=a*unit;return mc(`Red and blue counters are in the ratio ${a}:${b}. There are ${(a+b)*unit} counters. How many are red?`,c,[c+unit,c-unit,c+b,c+a,(a+b)*unit-b],{topic:'Ratio',skill:'Use a ratio to find a part',explanation:'Find the value of one ratio part, then multiply by the number of red parts.',difficulty:''},r)},
function(r){const l=r.int(7,24),w=r.int(4,15),c=l*w;return mc(`A rectangular garden is ${l} m long and ${w} m wide. What is its area?`,c,[2*(l+w),c+l,c+w,c-2,l*w+l],{topic:'Area',skill:'Calculate rectangular area',explanation:'Area of a rectangle is length × width.',difficulty:''},r)},
function(r){const l=r.int(6,24),w=r.int(3,15),c=2*(l+w);return mc(`A rectangular sign is ${l} cm long and ${w} cm wide. What is its perimeter?`,c,[l*w,c+2,c-2,l+w,2*l+w],{topic:'Perimeter',skill:'Calculate perimeter',explanation:'Add all four sides, or use 2 × (length + width).',difficulty:''},r)},
function(r){const base=r.int(6,30),step=r.int(2,8),vals=[base,base+step,base+2*step,base+3*step,base+4*step],c=vals.reduce((a,b)=>a+b,0)/vals.length;return mc(`Five scores are ${vals.join(', ')}. What is their mean?`,c,[c+step,c-step,base+step,c+2,base+2*step],{topic:'Data and averages',skill:'Calculate a mean',explanation:'Add all values and divide by the number of values.',difficulty:''},r)},
function(r){const start=r.int(4,30),step=r.pick([2,3,4,5,6,7,8,9]),vals=[start,start+step,start+2*step,start+3*step],c=start+4*step;return mc(`What number comes next? ${vals.join(', ')}, ?`,c,[c+step,c-step,c+2,c-2,start+5*step],{topic:'Patterns',skill:'Identify a constant difference',explanation:'Compare consecutive terms to find the repeated change.',difficulty:''},r)},
function(r){const h=r.int(7,17),m=r.pick([0,10,15,20,30,40,45,50]),dur=r.pick([25,35,45,50,65,75,90]);let total=h*60+m+dur;const hh=Math.floor(total/60)%24,mm=total%60,c=`${hh}:${String(mm).padStart(2,'0')}`;return mc(`A workshop starts at ${h}:${String(m).padStart(2,'0')} and lasts ${dur} minutes. When does it finish?`,c,[`${hh}:${String((mm+10)%60).padStart(2,'0')}`,`${(hh+1)%24}:${String(mm).padStart(2,'0')}`,`${hh}:${String((mm+20)%60).padStart(2,'0')}`,`${(hh+23)%24}:${String(mm).padStart(2,'0')}`,`${(hh+2)%24}:${String(mm).padStart(2,'0')}`],{topic:'Time',skill:'Add a duration to a clock time',explanation:'Convert the starting time to minutes, add the duration, then convert back.',difficulty:''},r)},
function(r){const price=r.pick([3.5,4,4.5,5,6,7.5,8]),qty=r.int(2,8),discount=r.pick([0.5,1,1.5,2]),c=(price-discount)*qty;return mc(`A notebook costs $${price.toFixed(2)}. A discount of $${discount.toFixed(2)} is taken from each notebook. How much do ${qty} notebooks cost?`,c,[price*qty,c+discount,c-discount,price*(qty-1),c+price],{topic:'Money',skill:'Apply a per-item discount',explanation:'Subtract the discount from the price of one item, then multiply by the quantity.',difficulty:''},r)},
