function(r){const total=r.int(8,20),fav=r.int(2,total-2),c=`${fav}/${total}`;return mc(`A bag contains ${fav} blue counters and ${total-fav} other counters. What is the probability of choosing blue?`,c,[`${fav+1}/${total}`,`${fav-1}/${total}`,`${fav}/${total-fav}`,`${total-fav}/${total}`,`${total}:${fav}`],{topic:'Probability',skill:'Represent probability as a fraction',explanation:'Probability = favourable outcomes ÷ total outcomes.',difficulty:''},r)},
function(r){const boxes=r.int(3,9),each=r.int(6,15),removed=r.int(2,each-1),c=boxes*each-removed;return mc(`There are ${boxes} boxes with ${each} pencils in each. ${removed} pencils are removed altogether. How many remain?`,c,[boxes*(each-removed),c+removed,c-each,boxes*removed,c+each],{topic:'Multi-step reasoning',skill:'Combine multiplication and subtraction',explanation:'Find the total number first, then subtract the number removed.',difficulty:''},r)},
function(r){const scale=r.pick([2,3,4,5,8,10]),cm=r.int(3,12),c=cm*scale;return mc(`On a map, 1 cm represents ${scale} km. Two towns are ${cm} cm apart. What is the actual distance?`,c,[cm+scale,c*2,c-scale,c+2*scale,cm*scale-scale],{topic:'Scale',skill:'Interpret a scale',explanation:'Multiply the map distance by the kilometres represented by each centimetre.',difficulty:''},r)},
function(r){const a=r.int(4,15),b=r.int(2,9),c0=r.int(2,8),c=a+b*c0;return mc(`Start with ${a}. Add ${b} groups of ${c0}. What is the result?`,c,[a+b+c0,(a+b)*c0,a+b*c0+c0,c+b,a+b],{topic:'Operations',skill:'Translate words into operations',explanation:'“Groups of” indicates multiplication before adding the starting amount.',difficulty:''},r)},
