function(r){const n=r.int(20,80),inc=r.pick([10,20,25,30,40]),increase=n*inc/100,c=n+increase;return mc(`A price of $${n} is increased by ${inc}%. What is the new price?`,c,[n+inc,n+increase/2,n+increase*2,n,n-increase],{topic:'Percentages',skill:'Increase a quantity by a percentage',explanation:'Calculate the percentage increase, then add it to the original amount.',difficulty:''},r)},
function(r){const per=r.pick([24,36,48,60]),part=r.pick([2,3,4,6]),c=per/part;return mc(`A ribbon ${per} cm long is cut into ${part} equal pieces. How long is each piece?`,c,[c+2,c-2,c*part,c+part,per-part],{topic:'Division',skill:'Divide a quantity into equal parts',explanation:'Equal pieces require the total length to be divided by the number of pieces.',difficulty:''},r)},
function(r){const a=r.int(2,9),b=r.int(3,10),c=a*b;return mc(`A rectangle has an area of ${c*4} cm² and a width of 4 cm. What is its length?`,c,[c+4,c-4,c*4,c/2,c+8],{topic:'Area',skill:'Find a missing dimension',explanation:'Length = area ÷ width.',difficulty:''},r)},
function(r){const whole=r.pick([60,80,100,120,150,200]),used=r.pick([15,20,25,30,40,50]),c=whole-used;return mc(`A class has ${whole} points and spends ${used} points. What percentage of the points remain?`,c*100/whole,[whole-used,used*100/whole,c,whole+used,whole-used-10],{topic:'Fractions and percentages',skill:'Convert a remaining fraction to a percentage',explanation:'Find the remaining amount, then compare it with the whole.',difficulty:''},r)},
function(r){const a=r.int(2,8),b=r.int(2,8),c=r.int(2,8),total=a+b+c;return mc(`Three shelves hold ${a}, ${b} and ${c} books. What is the ratio of books on the first shelf to all books?`,`${a}:${total}`,[`${a}:${b+c}`,`${total}:${a}`,`${b}:${total}`,`${a+b}:${total}`,`${a}:${total+1}`],{topic:'Ratio',skill:'Form a ratio from a total',explanation:'The ratio compares the first shelf with the total number of books.',difficulty:''},r)},
