function(r){const start=r.int(2,10),step=r.int(2,6),terms=6,c=start+(terms-1)*step;return mc(`A pattern starts at ${start} and increases by ${step} each time. What is the ${terms}th term?`,c,[start+terms*step,start+(terms-2)*step,c+step,c-step,start*terms],{topic:'Patterns',skill:'Find a later term',explanation:'There are five equal increases from the first to the sixth term.',difficulty:''},r)},
