function makeMath(seed){const r=R(seed),out=[];for(let i=0;i<35;i++){const item=mathFamilies[(seed*7+i*11)%mathFamilies.length](r);item.difficulty=difficulty(seed,i);item.id=`M-${String(seed).padStart(4,'0')}-${String(i+1).padStart(2,'0')}`;out.push(item)}return out}

