function(r){const a=r.int(3,7),b=a+r.int(1,4),c=a<b;return mc(`Which statement must be true when ${a} < ${b}?`,`${a} is less than ${b}`,[`${b} is less than ${a}`,`${a} equals ${b}`,`${a}+${b} is less than ${a}`,`${b}-${a}<0`],{topic:'Deduction',skill:'Apply an inequality directly',explanation:'The stated relationship is itself the condition that must hold.',difficulty:''},r)},
function(r){const c=r.pick(['triangle','square','pentagon','hexagon']);const sides={triangle:3,square:4,pentagon:5,hexagon:6}[c];return mc(`A regular ${c} has how many sides?`,sides,[sides+1,sides-1,sides*2],{topic:'Classification',skill:'Use a stated category property',explanation:'Identify the defining number of sides for the named shape.',difficulty:'Foundation'},r)},
