 F.push(r=>{const total=r.pick([48,60,72,84]),a=r.pick([2,3,4]),b=r.pick([3,4,5]),c0=r.pick([1,2,3]),parts=a+b+c0,unit=total/parts,third=c0*unit;return emc5(`A total of ${total} points is divided in the ratio ${a}:${b}:${c0}. How many points go to the third part?`,third,[unit,c0*parts,total-third,total/a,total/b],{topic:'Ratio',skill:'Divide a total in a three-part ratio',explanation:'Find the value of one ratio part, then multiply by the third ratio value.',difficulty:''},r)});
