 F.push(r=>{const n=r.int(2,9),a=r.int(3,10),b=r.int(2,8),c0=n*a+b,opts=[c0,c0+n,c0-a,n*a-b,(n+b)*a];return emc5(`A number n is multiplied by ${a}, then ${b} is added. If n=${n}, which statement is correct?`,`The output is ${c0}`,[`The output is ${n*a-b}`,`The output is ${(n+b)*a}`,`The output is ${c0+a}`,`The output is ${n+b}`],{topic:'Algebraic thinking',skill:'Evaluate a rule accurately',explanation:'Apply multiplication first and then addition exactly as stated.',difficulty:''},r)});
 F.push(r=>{const a=r.int(6,14),b=r.int(3,9),c0=r.int(2,7),outer=(a+c0)*(b+c0),inner=a*b,diff=outer-inner;return emc5(`A rectangle ${a} by ${b} is enlarged by adding ${c0} units to both dimensions. By how much does its area increase?`,diff,[c0*(a+b),c0*c0,outer,inner,diff+c0],{topic:'Area',skill:'Compare original and enlarged areas',explanation:'Find the new area and subtract the original area. The increase includes the corner square as well as the two strips.',difficulty:''},r)});
