 F.push(r=>{const n=r.int(5,12),d=r.int(2,6),last=n*d,prev=(n-1)*d,c=last-prev;return emc5(`A sequence has nth term ${d}n. What is the difference between the 10th term and the 7th term?`,d*3,[d,d*2,d*4,last-prev+d,10*d],{topic:'Sequences',skill:'Use a term rule to compare positions',explanation:'The position difference is 3, and each position changes by d.',difficulty:''},r)});
 for(let i=0;i<35;i++){const item=F[(seed*13+i*17)%F.length](r);item.difficulty=eliteDifficulty(seed,i);item.id=`M-${String(seed).padStart(4,'0')}-${String(i+1).padStart(2,'0')}`;out.push(item)}return out;
